def go_to(target, tol, maxit, grip):
    t = sw()[2]
    for i in range(maxit):
        d = [target[j] - t[j] for j in range(3)]
        dist = (d[0]*d[0] + d[1]*d[1] + d[2]*d[2]) ** 0.5
        if dist < tol:
